describe('Form Submission Error Handling', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should scroll to the error message on form submission failure', () => {
        cy.get('input[name="username"]').type('invalidUser'); // Simulate invalid input
        cy.get('input[name="password"]').type(''); // Leave password empty
        cy.get('form').submit(); // Submit the form

        cy.get('.error-message') // Replace with the actual selector for the error message
            .should('be.visible')
            .then(($error) => {
                const errorOffset = $error.offset().top;
                cy.window().then((win) => {
                    const scrollY = win.scrollY;
                    cy.wrap(scrollY).should('be.lessThan', errorOffset); // Ensure the error is scrolled into view
                });
            });
    });

    it('should not scroll if there are no error messages', () => {
        cy.get('input[name="username"]').type('validUser'); // Simulate valid input
        cy.get('input[name="password"]').type('validPassword'); // Simulate valid input
        cy.get('form').submit(); // Submit the form

        cy.get('.error-message') // Replace with the actual selector for the error message
            .should('not.exist'); // Ensure no error message is displayed

        cy.window().then((win) => {
            const scrollY = win.scrollY;
            expect(scrollY).to.equal(0); // Ensure the scroll position remains at the top
        });
    });
});
